contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt withdrawGovernanceAsset for a targetContract and asset, from this contract as msg.sender.
    // Inputs:
    // - targetContract: the contract for which a pendingFlashDecision may exist
    // - asset: the ERC20 asset address expected in the pending decision
    function run(address targetContract, address asset) public payable {
        require(true);

        // Read prior pending decision fields for this contract (msg.sender is this test contract)
        (uint256 before_amount, uint256 before_unlockTime, address before_asset) = c.pendingFlashDecision(targetContract, address(this));

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call, read the pending decision again
        (uint256 after_amount, uint256 after_unlockTime, address after_asset) = c.pendingFlashDecision(targetContract, address(this));

        // General rule asserted:
        // If the call reverted, then it must be that the stored asset did not match, or amount was zero, or unlockTime not passed.
        // If the call succeeded, then the pending record for (targetContract, this) is cleared (amount == 0).
        assert(
            reverted
            ? (
                // revert implies at least one of the require conditions in withdrawGovernanceAsset failed
                // Observe that matches: asset mismatch OR amount == 0 OR unlockTime >= now
                // We cannot read block.timestamp here, but we can relate before_unlockTime and before_amount and before_asset
                // A revert should occur when NOT (before_asset == asset && before_amount > 0 && before_unlockTime < block.timestamp)
                // We conservatively assert that if before_amount > 0 and before_asset == asset then after_amount == before_amount || reverted
                // but must encode purely observable relation: when reverted, it's NOT the case that (before_asset == asset && before_amount > 0 && before_unlockTime < before_unlockTime + 1)
                // Simpler checked property: if reverted then either before_asset != asset or before_amount == 0 or after_amount == before_amount
                (before_asset != asset) || (before_amount == 0) || (after_amount == before_amount)
              )
            : (
                // If succeeded, then after_amount must be zero (record deleted). This is the key invariant.
                after_amount == 0
              )
        );
    }

    receive() external payable {}
}

