contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to withdraw a pending flash governance asset for (targetContract) as this contract (msg.sender).
    // Inputs:
    // - targetContract: the contract for which a pendingFlashDecision may exist
    // - asset: the ERC20 asset address we attempt to withdraw
    function run(address targetContract, address asset) public payable {
        require(true);

        // Read the pending decision before the call for (targetContract, this)
        (uint256 before_amount, uint256 before_unlockTime, address before_asset, bool before_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the pending decision after the call
        (uint256 after_amount, uint256 after_unlockTime, address after_asset, bool after_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        // General rule:
        // If the call succeeded (not reverted) then the pending amount must be cleared to 0.
        // If the call reverted then either the before-record did not permit withdrawal (asset mismatch or zero amount or unlockTime >= now)
        // or the record remained unchanged (conservative observable outcome).
        assert(
            reverted
            ? (
                // reverted: either asset mismatch or amount==0 or unlockTime >= now OR no observable change to the record
                (before_asset != asset) || (before_amount == 0) || (before_unlockTime >= block.timestamp) || (
                    after_amount == before_amount && after_asset == before_asset && after_unlockTime == before_unlockTime && after_assetBurnable == before_assetBurnable
                )
              )
            : (
                // succeeded: the pending amount was cleared
                after_amount == 0
              )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to withdraw a pending flash governance asset for (targetContract) as this contract (msg.sender).
    // Inputs:
    // - targetContract: the contract for which a pendingFlashDecision may exist
    // - asset: the ERC20 asset address we attempt to withdraw
    function run(address targetContract, address asset) public payable {
        require(true);

        // Observe the pending decision before the call for (targetContract, this)
        (uint256 before_amount, uint256 before_unlockTime, address before_asset, bool before_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        // Observe c's balance of the asset contract by calling balanceOf(asset) on the IERC20 via the asset interface if possible.
        // We can only observe address(c).balance for ETH; ERC20 balances require calling the token's balanceOf. We will try to read IERC20(asset).balanceOf(address(c)).
        uint256 c_balance_before;
        bool readTokenBalance = true;
        // Make a low-level staticcall to asset.balanceOf(address) to avoid importing IERC20 here (observe only public surface).
        // Prepare calldata for balanceOf(address) -> function selector 0x70a08231
        bytes memory callData = abi.encodeWithSelector(bytes4(0x70a08231), address(c));
        (bool ok, bytes memory ret) = asset.staticcall(callData);
        if (ok && ret.length >= 32) {
            c_balance_before = abi.decode(ret, (uint256));
        } else {
            // Couldn't read token balance (non-ERC20), mark as unreadable
            readTokenBalance = false;
            c_balance_before = 0;
        }

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the pending decision after the call
        (uint256 after_amount, uint256 after_unlockTime, address after_asset, bool after_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        // If the call succeeded (did not revert), then the pending amount must be cleared to 0.
        // If the call reverted, then either the before-record did not permit withdrawal (asset mismatch or amount==0 or unlockTime >= now)
        // or nothing observable changed to the pendingFlashDecision record.
        // Additionally, if the call succeeded and the asset implements balanceOf, c's token balance should have decreased by before_amount.

        bool token_balance_decreased_if_readable = true;
        if (!reverted && readTokenBalance) {
            // read balance after
            (bool ok2, bytes memory ret2) = asset.staticcall(callData);
            uint256 c_balance_after = 0;
            if (ok2 && ret2.length >= 32) {
                c_balance_after = abi.decode(ret2, (uint256));
                // c_balance_after should be c_balance_before + before_amount ? WAIT: withdrawGovernanceAsset transfers to msg.sender (this contract), so token moved from c to this
                // c_balance should decrease by before_amount when successful
                if (before_amount > c_balance_before) {
                    // underflow situation in expectation: can't assert decrease reliably, mark as false to avoid incorrect failure
                    token_balance_decreased_if_readable = false;
                } else {
                    token_balance_decreased_if_readable = (c_balance_after + before_amount == c_balance_before);
                }
            } else {
                token_balance_decreased_if_readable = false;
            }
        }

        assert(
            reverted
            ? (
                // reverted: either asset mismatch or amount==0 or unlockTime >= now OR no observable change to the record
                (before_asset != asset) || (before_amount == 0) || (before_unlockTime >= block.timestamp) || (
                    after_amount == before_amount && after_asset == before_asset && after_unlockTime == before_unlockTime && after_assetBurnable == before_assetBurnable
                )
              )
            : (
                // succeeded: the pending amount was cleared
                after_amount == 0 && (
                    // if token balance was readable we expect c's token balance decreased by before_amount
                    (!readTokenBalance) || token_balance_decreased_if_readable
                )
              )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We will attempt withdrawGovernanceAsset for a given targetContract and asset.
    // Precondition: none on c state. We only observe public getters and whether the call reverts.
    function run(address targetContract, address asset) public payable {
        // Read pending entry before the call via the public getter pendingFlashDecision.
        // The getter returns (amount, unlockTime, asset, assetBurnable) packed as FlashGovernanceConfig.
        // However in the original contract pendingFlashDecision is mapping to FlashGovernanceConfig and getter
        // will return the struct fields in declared order. We'll read via the autogenerated getter.

        (uint256 before_amount, uint256 before_unlockTime, address before_asset, bool before_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        bool reverted;
        // attempt call; withdrawGovernanceAsset may revert if conditions not met
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read pending entry after the call
        (uint256 after_amount, uint256 after_unlockTime, address after_asset, bool after_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        // Rule: if the call did not revert, then the withdrawn asset and amount must have matched the pending entry before the call,
        // and after the call the pending amount for (targetContract, caller) is zero (entry cleared).
        // Also if it didn't revert, the before_amount must have been > 0 and before_asset must equal the provided asset, and before_unlockTime < block.timestamp.
        assert(
            reverted || (
                before_amount > 0 &&
                before_asset == asset &&
                before_unlockTime < block.timestamp &&
                after_amount == 0 &&
                after_asset == address(0) &&
                // After unlockTime is cleared to 0 as part of delete; assetBurnable false is acceptable but delete sets everything to default
                after_unlockTime == 0
            )
        );
    }

    receive() external payable {}
}

