contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a targetContract address and an asset address as inputs. The test will
    // attempt to withdrawGovernanceAsset for msg.sender == address(this) (InvMutTest).
    // The property: after the call, either it reverted and the pending entry (if observed before)
    // is unchanged, or it succeeded and the pending entry is cleared and the asset amount was
    // transferred to this contract (observable via address(this).balance only for ETH; for ERC20
    // we can only observe via the view getter pendingFlashDecision).

    // Because we can only observe c via its public getters, we will read pendingFlashDecision
    // for (targetContract, address(this)) before the call (via the autogenerated getter), then
    // attempt the withdrawal, then read it again. The rule: if the call succeeded then the
    // post-read must have amount == 0 (deleted), and if it reverted then the post-read equals pre-read.

    // Note: pendingFlashDecision is a public mapping returning the FlashGovernanceConfig
    // struct (amount, unlockTime, asset, assetBurnable). The autogenerated getter returns
    // (uint256,uint256,address,bool).

    function run(address targetContract, address asset) public payable {
        // No preconditions on params
        // Read the pending configuration for (targetContract, this contract)
        (uint256 pre_amount, uint256 pre_unlockTime, address pre_asset, bool pre_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        bool reverted;
        // call withdrawGovernanceAsset and catch revert
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 post_amount, uint256 post_unlockTime, address post_asset, bool post_assetBurnable) = c.pendingFlashDecision(targetContract, address(this));

        // Assert the general rule:
        // - If the call reverted, pending state is unchanged.
        // - If the call succeeded, the pending amount must be cleared (amount == 0) and asset/address fields may be zeroed.
        assert(
            (reverted && pre_amount == post_amount && pre_unlockTime == post_unlockTime && pre_asset == post_asset && pre_assetBurnable == post_assetBurnable)
            || (!reverted && post_amount == 0)
        );
    }

    receive() external payable { }
}

