contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single entry that encodes the property
    function run(address callerConfigurable, bool enforceToggle, int256 v1, int256 v2) public payable {
        // Preconditions: we must not assume anything about c's internal state; only use provided params.
        // Make sure the callerConfigurable is not zero to allow setEnforcement call on it as msg.sender
        require(callerConfigurable != address(0));

        // 1) Toggle enforcement for the test contract (InvMutTest) by calling c.setEnforcement from the chosen configurable
        // The Governable.setEnforcement function sets enforceLimitsActive[msg.sender] = enforce.
        // We need to perform the call as if from callerConfigurable. Since the checker runs this single transaction
        // and all calls from this test contract have msg.sender == address(this), we emulate calls by invoking
        // the target function directly: setEnforcement is public on C, so calling it will set enforceLimitsActive[address(this)].
        // To use callerConfigurable as the source of enforcement flag, we instead rely on the provided boolean enforceToggle
        // and call setEnforcement(enforceToggle) directly (this sets enforceLimitsActive[address(this)]).
        c.setEnforcement(enforceToggle);

        // 2) Now call enforceToleranceInt (which converts to absolute uints and calls enforceTolerance)
        // Capture whether it reverts.
        bool reverted;
        try c.enforceToleranceInt(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables: we can read configured() via the public configured getter on Configurable? Note: C has a function configured() inherited from Configurable? 
        // In C, there is a public bool configured in Governable (named configured), so there is an auto getter c.configured().
        bool cfg = c.configured();

        // Also read enforceLimitsActive for this contract via public mapping? enforceLimitsActive is private mapping, but there is no getter.
        // However, setEnforcement affects enforceLimitsActive[msg.sender] where msg.sender is this test contract; we cannot directly read it.
        // Instead, we use the logical relation: if enforcement is not active OR the caller (address(this)) is not configured as Configurable, enforceTolerance must return (not revert).
        // We can observe cfg and the boolean we set (enforceToggle) to build the assertion.

        // Build absolute uints as enforceToleranceInt would
        uint256 uv1 = v1 >= 0 ? uint256(v1) : uint256(-v1);
        uint256 uv2 = v2 >= 0 ? uint256(v2) : uint256(-v2);

        // Formulate the general rule: if enforcement is disabled for this contract (enforceToggle == false) OR c is not configured (cfg == false), then enforceToleranceInt must NOT revert.
        // Otherwise (enforceToggle==true && cfg==true), revert can occur only if the FE1 condition holds (i.e., tolerance check fails). We encode that: if it did NOT revert, then the tolerance condition holds.

        // The assertion is a single general statement combining both directions.
        assert(
            // If enforcement disabled for this test contract OR contract not configured, then call must succeed
            (!enforceToggle || !cfg) ? (reverted == false) :
            // Else enforcement active and configured: if reverted==false then the tolerance check must have been satisfied
            (
                reverted == true ? true : (
                    // tolerance check satisfied: replicate enforceTolerance logic to ensure no FE1
                    (uv1 > uv2) ? (
                        (uv2 == 0) ? (uv1 <= 1) : (((uv1 - uv2) * 100) < uint256(c.security().changeTolerance) * uv1)
                    ) : (
                        (uv1 == 0) ? (uv2 <= 1) : (((uv2 - uv1) * 100) < uint256(c.security().changeTolerance) * uv1)
                    )
                )
            )
        );
    }

    receive() external payable {}
}

