    // single public function with inputs to exercise withdrawGovernanceAsset
    function run(address targetContract, address asset) public payable {
        // read pending decision state before call
        (uint256 before_amount, , , , ) = c.flashGovernanceConfig(); // get some public to satisfy reading; we won't rely on it

        // capture balance of this test and of contract c for later observation
        uint256 beforeTestBal = address(this).balance;
        uint256 beforeCBal = address(c).balance;

        // attempt the withdraw; it may revert
        bool reverted;
        try c.withdrawGovernanceAsset{value: 0}(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, either it reverted OR the pendingFlashDecision entry for (targetContract, this contract)
        // must have been cleared and funds transferred: We can observe that by checking that either
        // - the call reverted, or
        // - this contract's balance increased by the withdrawn amount and the pending entry no longer matches the asset/amount predicate
        // We cannot read the internal mapping directly, but withdrawGovernanceAsset deletes pendingFlashDecision[targetContract][msg.sender].
        // To check deletion we rely on the public getter pendingFlashDecision which is declared public in C: mapping(address => mapping(address => FlashGovernanceConfig)) public pendingFlashDecision;
        // The auto-generated getter has signature: function pendingFlashDecision(address, address) returns (uint256 amount, uint256 unlockTime, address asset, bool assetBurnable)

