        uint256 afterTestBal = address(this).balance;
        uint256 afterCBal = address(c).balance;

        // General rule:
        // If the call did not revert, then either the withdrawn amount was zero (nothing transferred) OR our balance increased by that amount,
        // and the pendingFlashDecision entry must have been cleared (amount == 0 and asset != the requested asset or unlockTime == 0).
        // Formulate assert capturing that: reverted OR (after_amount == 0 && (after_asset != asset || after_unlockTime == 0) && afterTestBal >= beforeTestBal && afterCBal <= beforeCBal + (afterTestBal - beforeTestBal));

        assert(
            reverted || (
                // pending entry cleared
                after_amount == 0 && (after_asset != asset || after_unlockTime == 0) &&
                // funds not magically lost: our balance did not decrease
                afterTestBal >= beforeTestBal
            )
        );
    }

    receive() external payable {}
}

