contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary inputs
    function run(address callerAddr, int256 v1, int256 v2, bool setEnforce) public payable {
        require(callerAddr != address(0));

        // Read pre-state via public getters
        bool configured = c.configured(); // Configurable configured()
        // enforceLimitsActive is public mapping so there's a getter: enforceLimitsActive(address)
        bool beforeEnforce = c.enforceLimitsActive(callerAddr);

        // We will try to call enforceToleranceInt and catch whether it reverts.
        bool reverted;
        try c.enforceToleranceInt(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule we assert:
        // If enforcement is not active for caller OR the caller (as Configurable) is not configured OR global configured() is false,
        // then enforceToleranceInt should not revert. Otherwise, when enforcement is active and configured, then a revert implies
        // the numeric FE1 condition failed: the absolute difference scaled by 100 is >= changeTolerance * minNonzero.
        // We express the safe side: if enforcement not active or not configured then reverted == false.

        // Build condition: enforcement effectively active for caller requires beforeEnforce==true AND Configurable(caller).configured()==true AND configured==true
        bool callerConfigured;
        // We cannot call Configurable(callerAddr).configured() directly on arbitrary address if it's not a contract — that would revert.
        // So conservatively call via low-level staticcall to read configured() and treat non-contract or failing call as false.
        bytes memory payload = abi.encodeWithSignature("configured()");
        (bool ok, bytes memory ret) = callerAddr.staticcall(payload);
        if (ok && ret.length >= 32) {
            callerConfigured = abi.decode(ret, (bool));
        } else {
            callerConfigured = false;
        }

        bool enforcement_effective = beforeEnforce && callerConfigured && configured;

        assert((!enforcement_effective && reverted == false) || (enforcement_effective));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary inputs
    function run(address callerAddr, int256 v1, int256 v2, bool callerSetsEnforce) public payable {
        require(callerAddr != address(0));

        // Read global configured flag from c
        bool globalConfigured = c.configured();

        // We cannot read c.enforceLimitsActive(mapping) directly (no public getter), so we will simulate
        // the caller having set enforcement by attempting to call c.setEnforcement from this test contract
        // via a call that sets msg.sender to callerAddr is impossible. Instead, we conservatively detect
        // whether the caller (callerAddr) is a contract that reports configured()==true. If callerConfigured==false
        // then enforcement cannot be effective because Configurable(caller).configured() must be true for enforcement.

        // Probe callerAddr.configured() via staticcall; treat failures or non-contract as false.
        bool callerConfigured;
        bytes memory payload = abi.encodeWithSignature("configured()");
        (bool ok, bytes memory ret) = callerAddr.staticcall(payload);
        if (ok && ret.length >= 32) {
            callerConfigured = abi.decode(ret, (bool));
        } else {
            callerConfigured = false;
        }

        // Now call enforceToleranceInt and observe whether it reverts.
        bool reverted;
        try c.enforceToleranceInt(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rules: If globalConfigured == false OR callerConfigured == false then enforcement is not effective for caller,
        // and enforceToleranceInt should NOT revert (function returns normally). Because when not configured the function returns early.
        // We assert that in those cases reverted == false. Otherwise we do not constrain (the function may revert depending on enforcement state).

        assert((!globalConfigured || !callerConfigured) ? (reverted == false) : true);
    }

    receive() external payable {}
}

