contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to withdraw a pending flash governance decision for (targetContract, asset)
    // Inputs:
    // - target: the targetContract key used in pendingFlashDecision
    // - asset: the asset address to match pendingFlashDecision[..].asset
    // Note: msg.sender inside calls to c will be this contract (the InvMutTest instance).
    function run(address target, address asset) public payable {
        require(true);

        // Read the pending entry before the withdraw attempt via the public getter
        // pendingFlashDecision is a public mapping returning a struct with fields (amount, unlockTime, asset, assetBurnable)
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeAssetBurnable) = c.pendingFlashDecision(target, address(this));

        bool reverted;
        // Attempt the withdrawGovernanceAsset call and capture if it reverts
        try c.withdrawGovernanceAsset(target, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the pending entry after the withdraw attempt
        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterAssetBurnable) = c.pendingFlashDecision(target, address(this));

        // General rule:
        // If the call succeeded (not reverted) then it must have transferred exactly the 'beforeAmount' and cleared the pending entry
        // i.e., afterAmount == 0 and beforeAmount > 0 implies the asset matched and unlockTime was in the past.
        // Conversely, if it reverted then the pending entry must be unchanged (conservative rule): afterAmount == beforeAmount
        // We express a single assert combining these implications.
        assert(
            (!reverted && afterAmount == 0 && (beforeAmount == 0 || (beforeAsset == asset && beforeAmount > 0 && beforeUnlockTime < block.timestamp)))
            || (reverted && afterAmount == beforeAmount)
        );
    }

    receive() external payable {}
}

